UPDATE PEACH_TENANT_INVITATION
SET STATUS = 'EXPIRED', VERSION = VERSION + 1
WHERE TENANT_REF_ID = #{tenantRefId}
  AND INVITEE_USER_REF_ID = #{userRefId}
  AND STATUS = 'PENDING' AND IS_DELETE = 0
  AND EXPIRES_AT  <=  CURRENT_TIMESTAMP(3)

mapper.select:
SELECT 
FROM PEACH_TENANT_INVITATION
WHERE ID = #{id} AND TENANT_REF_ID = #{tenantRefId}

mapper.update:
UPDATE PEACH_TENANT_INVITATION
SET STATUS = 'ACCEPTED', VERSION = VERSION + 1
WHERE ID = #{id} AND TENANT_REF_ID = #{tenantRefId}
  AND INVITEE_USER_REF_ID = #{userRefId}
  AND VERSION = #{version} AND STATUS = 'PENDING'
  AND IS_DELETE = 0 AND EXPIRES_AT > CURRENT_TIMESTAMP(3)
